// ── Technology KIND (2026 internet-benchmark audit) ──────────────────────────
// Every one of the first 169 entries was a PART SUBSTITUTION ("X replaces Y"),
// because `replaces` is a required field and the research prompt asked only for
// displacement. Benchmarking the register against live internet research on air
// suspension exposed the blind spot: three real technologies were missing and
// all three were non-substitutions — a new FUNCTION from existing hardware
// (aero ride-height bought range), a SOFTWARE layer coordinating actuators it
// replaces none of, and a LIFECYCLE change (health monitoring displacing
// warranty cost). A register that can only see swaps cannot see those.
//
//   substitution  a new part/process displaces an incumbent one   (default)
//   function      existing hardware earns a new job + new business case
//   orchestration a software layer coordinating actuators it does not replace
//   lifecycle     service/warranty/maintenance model shift
//
// `replaces` stays REQUIRED for every kind — but for non-substitutions it names
// what is displaced in COST terms (battery kWh, warranty claims, calibration
// loops), which is what a cost engineer actually needs to hear.
export const TECH_KINDS = ['substitution', 'function', 'orchestration', 'lifecycle'];

// Compact constructor keeps the entries readable.
const t = (id, name, commodity, powertrains, replaces, trl, adoptionPct, drivers, costTrend, players, note, matchTerms, extra) =>
  ({ id, name, commodity, powertrains, replaces, trl, adoptionPct, drivers, costTrend, players, note, matchTerms, kind: 'substitution', ...extra });

